const raw = $input.first().json;
// Webhook body is usually flattened onto $json
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const headers = raw.headers || {};
const headerSecret =
  headers['x-gtm-webhook-secret'] ||
  headers['X-Gtm-Webhook-Secret'] ||
  '';
const envSecret = String($env.GTM_WEBHOOK_SECRET || '');
const provided =
  headerSecret ||
  body.gtmWebhookSecret ||
  body.webhookSecret ||
  '';
const secretOk = Boolean(envSecret) && provided === envSecret;

if (!secretOk) {
  return [{
    json: {
      secretOk: false,
      error: 'UNAUTHORIZED',
      jobId: body.jobId || null,
    },
  }];
}

const jobId = body.jobId;
const domain = body.domain;
const normalizedUrl = body.normalizedUrl || `https://${domain}`;
const profileId = body.profileId;
const callbackUrl = body.callbackUrl;
const attributes = Array.isArray(body.attributes)
  ? body.attributes
  : (body.profile && body.profile.attributes) || [];

if (!jobId || !domain || !callbackUrl || !attributes.length) {
  return [{
    json: {
      secretOk: true,
      payloadOk: false,
      error: 'INVALID_PAYLOAD',
      jobId: jobId || null,
      callbackUrl: callbackUrl || null,
    },
  }];
}

const attrLines = attributes.map((a, i) => {
  const prompt = String(a.researchPrompt || '').replaceAll('{domain}', domain);
  return [
    `${i + 1}. id=${a.id} label=${a.label}`,
    `   research: ${prompt}`,
    `   positive: ${(a.positiveSignals || []).join('; ')}`,
    `   negative: ${(a.negativeSignals || []).join('; ')}`,
  ].join('\n');
}).join('\n');

const researchPrompt = [
  `You are researching public web signals about company domain: ${domain} (${normalizedUrl}).`,
  `Profile: ${profileId}.`,
  'For EACH attribute below, return a finding with attributeId, present (true|false|unknown), confidence 0-1, scoreHint 0-100, evidence[{snippet, sourceUrl?}], notes?.',
  'Return JSON only: {"findings":[...]} matching every attribute id. No markdown fences.',
  'Do not invent certifications or customers not supported by public sources; use present=unknown when unsure.',
  '',
  'Attributes:',
  attrLines,
].join('\n');

return [{
  json: {
    secretOk: true,
    payloadOk: true,
    jobId,
    domain,
    normalizedUrl,
    profileId,
    callbackUrl,
    attributes,
    researchPrompt,
    perplexityModel: $env.PERPLEXITY_RESEARCH_MODEL || 'perplexity/sonar',
    openRouterModel: $env.OPENROUTER_STRATEGY_MODEL || 'x-ai/grok-4.3',
    startedAt: Date.now(),
  },
}];

